import * as T from './assets/three.module.js';
import {makeStars,makePipeline} from './spacefx.js';
import {sceneNavigation} from './scene-navigation.js';
import {capture4K,disposeObject,graphicsQuality,softSprite} from './graphics.js';
import {galaxyPoint,hubbleVelocity} from './simulation-math.js';
const $=s=>document.querySelector(s);
const modes=[['galaxy','Island of stars'],['nebula','Stellar nursery'],['web','Cosmic web'],['collision','Galactic encounter'],['expansion','Expanding space'],['supernova','Stellar explosion']];
const descriptions={galaxy:['A hundred thousand points of possibility.','A procedural spiral galaxy. Change its arm count, dust and star density; orbit through the disk and inspect a star.','Spiral structure is generated, not a map of the Milky Way. Differential rotation is accelerated and illustrative.'],nebula:['The universe is still making things.','Fly around a glowing volume of interstellar gas. Adjust density and observe how different wavelengths reveal different structures.','Procedural volume rendering with synthetic emission and dust. Wavelength palettes are illustrative, not measured telescope channels.'],web:['The space between galaxies has structure.','Explore knots, filaments and voids. Every luminous node represents a cluster of galaxies in this generated cosmic web.','Schematic large-scale structure. This is a generated network, not an observational survey or cosmological simulation.'],collision:['A meeting that changes both galaxies.','Scrub a close encounter. Stellar streams stretch into tidal tails as two rotating disks pass one another.','An illustrative encounter, not an N-body calculation. Stars are displaced by a visual deformation model; no collision prediction is made.'],expansion:['More space. Between everything.','Change the scale factor and Hubble constant. Select a node to compare its distance and recession speed in a low-redshift reference.','Uniform scale-factor demonstration. v = H₀d is a local approximation, not a relativistic distance model or expansion inside bound galaxies.'],supernova:['One star. An extraordinary ending.','Trigger a stellar explosion and scrub the outward-moving shell. Explore the remnant from any angle.','An artistic ejecta and shock-front model with a normalized timeline. Nuclear burning, radiation transport and real explosion times are not solved.']};
export function setupUniverse(api,gfx){
 const section=document.createElement('section');section.id='universe';section.className='universe-section wrap';section.innerHTML=`<div class="section-heading universe-heading"><div><span class="eyebrow">BEYOND THE SOLAR SYSTEM / THE UNIVERSE ATELIER</span><h2>NOTHING SMALL<br>ABOUT <em>INFINITY.</em></h2></div><p>Galaxies. Clouds of creation. Cosmic structure.<br>Six scenes. A universe you can touch.</p></div><div class="universe-shell"><div class="universe-tabs" role="group" aria-label="Universe simulation">${modes.map(([id,name],i)=>`<button data-universe="${id}" aria-pressed="${!i}"><span>0${i+1}</span>${name}</button>`).join('')}</div><div class="universe-stage"><div id="universe-render" tabindex="0" role="img" aria-label="Interactive universe. Drag to orbit, shift-drag to pan, plus/minus to zoom. Select luminous nodes to inspect."></div><div class="universe-caption"><span id="universe-chapter">01 / GALACTIC STRUCTURE</span><h3 id="universe-title"></h3><p id="universe-description"></p></div><div id="universe-inspect" class="universe-inspect" role="status">Select a star or cluster to inspect it.</div><div class="universe-transport"><button id="universe-pause" aria-pressed="false">Pause</button><button id="universe-camera">Reset view ↺</button><button id="universe-auto" aria-pressed="true">Cinematic orbit</button><button id="universe-capture">Capture 4K ↧</button><button id="universe-burst">Trigger event ✦</button></div><span class="universe-gesture">DRAG / ORBIT · SHIFT + DRAG / PAN · CLICK / INSPECT · + − / ZOOM</span></div><div class="universe-console"><label>Time flow<input id="universe-speed" type="range" min="0" max="4" step=".05" value="1"></label><label>Star density<input id="universe-density" type="range" min="15" max="100" value="80"></label><label data-universe-param="arms">Spiral arms<select id="universe-arms"><option>2</option><option selected>4</option><option>6</option></select></label><label data-universe-param="gas">Gas / dust density<input id="universe-gas" type="range" min=".2" max="2" step=".05" value="1"></label><label>View spectrum<select id="universe-spectrum"><option value="natural">Optical / illustrative color</option><option value="infrared">Infrared / warm dust</option><option value="energy">High energy / violet blue</option></select></label><label data-universe-param="age">Encounter / event timeline<input id="universe-age" type="range" min="0" max="1" step=".001" value="0"></label><label data-universe-param="scale">Scale factor<input id="universe-scale" type="range" min=".5" max="2.5" step=".01" value="1"></label><label data-universe-param="hubble">Hubble reference / km s⁻¹ Mpc⁻¹<input id="universe-hubble" type="range" min="50" max="90" value="70"></label><div class="universe-toggles"><label><input id="universe-dust" type="checkbox" checked> Dust & gas</label><label><input id="universe-stars" type="checkbox" checked> Stars</label><label><input id="universe-filaments" type="checkbox" checked> Filaments / guides</label><label><input id="universe-bloom" type="checkbox" checked> Optical glow</label></div></div><div class="universe-footer"><span id="universe-stats">LOCAL / PROCEDURAL UNIVERSE</span><p id="universe-note"></p><a href="https://science.nasa.gov/universe/galaxies/" target="_blank" rel="noopener">Explore the science ↗</a></div></div>`;
 $('#singularity').after(section);let mode='galaxy',started=false,visible=false,scene,camera,renderer,nav,pipeline,cloud,stars,dust,filaments,volume,core,objects=new T.Group(),time=0,last=0,paused=false,auto=true,eventAge=0,eventRunning=false,selected=null,uiClock=0;
 const root=$('#universe-render'),sprite=softSprite();let pointUniforms=[],volumeUniforms,nodes=[];
 function updateText(){const d=descriptions[mode];$('#universe-title').textContent=d[0];$('#universe-description').textContent=d[1];$('#universe-note').textContent=d[2];$('#universe-chapter').textContent=`0${modes.findIndex(m=>m[0]===mode)+1} / ${modes.find(m=>m[0]===mode)[1].toUpperCase()}`;const show={arms:['galaxy','collision'],gas:['galaxy','nebula'],age:['collision','supernova'],scale:['expansion'],hubble:['expansion']};section.querySelectorAll('[data-universe-param]').forEach(el=>el.hidden=!show[el.dataset.universeParam].includes(mode));$('#universe-burst').hidden=!['supernova','collision'].includes(mode);$('#universe-inspect').textContent=['web','expansion'].includes(mode)?'Select a luminous cluster to compare its scale.':'Select a star or use the simulation controls.';}
 function initialize(){started=true;try{renderer=gfx.rendererFor(root);scene=new T.Scene();scene.background=new T.Color(0x03050b);camera=new T.PerspectiveCamera(52,1,.03,1200);gfx.observeSize(root,renderer,camera);scene.add(makeStars(3200,200),objects);nav=sceneNavigation(root,camera,{distance:34,pitch:.6,yaw:.3});pipeline=makePipeline(renderer,scene,camera);build();requestAnimationFrame(frame);}catch(e){root.innerHTML='<p class="fallback-message">3D is unavailable in this browser. Select a scene to read its model and scale notes.</p>';$('#universe-stats').textContent='BASIC GRAPHICS / SCENE GUIDE';$('#universe-capture').disabled=true;}}
 function pointCloud(positions,colors,sizes,kind=0){const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(positions,3));geometry.setAttribute('color',new T.Float32BufferAttribute(colors,3));geometry.setAttribute('size',new T.Float32BufferAttribute(sizes,1));const uniforms={time:{value:0},spectrum:{value:0},kind:{value:kind},age:{value:0},scaleFactor:{value:1},pixelRatio:{value:1},gain:{value:1}};pointUniforms.push(uniforms);const material=new T.ShaderMaterial({uniforms,vertexColors:true,transparent:true,depthWrite:false,blending:T.AdditiveBlending,vertexShader:`attribute float size;varying vec3 tint;uniform float time,kind,age,scaleFactor,pixelRatio;void main(){vec3 p=position;float r=length(p.xz);if(kind<1.5){float a=time*.06/(1.+r*.12),c=cos(a),s=sin(a);p.xz=mat2(c,-s,s,c)*p.xz;}if(kind>.5&&kind<1.5){float side=step(0.,position.y)*2.-1.;p.y=abs(p.y)-.3;float phase=age*6.283;p.x+=side*(7.-age*12.);p.z+=side*sin(phase)*3.;p.y+=side*sin(phase*.5)*2.;float pull=pow(age,2.)*pow(r/12.,2.);p.x+=side*pull*8.;p.z+=sin(r*.4+phase)*pull*4.;}if(kind>2.5&&kind<3.5)p*=scaleFactor;if(kind>3.5){p*=.12+age*2.4;p.y+=sin(age*5.+r)*age*.2;}tint=color;vec4 mv=modelViewMatrix*vec4(p,1.);gl_PointSize=clamp(size*pixelRatio*100./max(1.,-mv.z),.7,25.);gl_Position=projectionMatrix*mv;}`,fragmentShader:`varying vec3 tint;uniform float spectrum,gain;void main(){vec2 q=gl_PointCoord-.5;float r=length(q);if(r>.5)discard;float glow=exp(-r*r*22.)*.7+pow(max(0.,1.-r*2.),6.)*.8;vec3 c=tint;if(spectrum>.5&&spectrum<1.5)c=mix(c,vec3(1.,.3,.06),.7);if(spectrum>1.5)c=mix(c,vec3(.28,.22,1.),.7);gl_FragColor=vec4(c*1.4,glow*gain);}`});const p=new T.Points(geometry,material);objects.add(p);return p;}
 function galaxy(collision=false){const count=120000,p=[],colors=[],sizes=[],dp=[],dc=[],ds=[],arms=+$('#universe-arms').value;for(let i=0;i<count;i++){const v=galaxyPoint(i,count,arms),bulge=i%7===0;if(bulge){const r=((i*.6180339)%1)*2,a=i*2.39996;v.x=Math.cos(a)*r;v.z=Math.sin(a)*r;v.y=Math.sin(i*1.7)*Math.sqrt(Math.max(0,4-r*r))*.35;}p.push(v.x,collision?(i%2?1:-1)*(.3+Math.abs(v.y)):v.y,v.z);const mix=Math.min(1,v.r/9);colors.push(1-mix*.55,.64+mix*.12,.3+mix*.7);sizes.push(i%101===0?2.1:.5+(i%13)/20);if(i%5===0){dp.push(v.x*1.02,v.y*1.5,v.z*1.02);dc.push(.45+mix*.15,.13+mix*.18,.06+mix*.28);ds.push(7+(i%9));}}stars=pointCloud(p,colors,sizes,collision?1:0);dust=pointCloud(dp,dc,ds,collision?1:0);dust.material.opacity=.35;const glow=new T.Sprite(new T.SpriteMaterial({map:sprite,color:0xffc791,transparent:true,opacity:.8,blending:T.AdditiveBlending,depthWrite:false}));glow.scale.set(5,3.5,1);if(!collision)objects.add(glow);core=glow;}
 function web(expanding=false){nodes=Array.from({length:52},(_,i)=>{const a=i*2.399963,r=5+((i*37)%113)/7;return new T.Vector3(Math.cos(a)*r,Math.sin(i*3.81)*9,Math.sin(a)*r)});const positions=[],colors=[],sizes=[];for(let i=0;i<42000;i++){const n=nodes[i%nodes.length],r=((i*.6180339)%1)**2*.8,a=i*2.399963;positions.push(n.x+Math.cos(a)*r,n.y+Math.sin(i*1.7)*r,n.z+Math.sin(a)*r);colors.push(.35+(i%7)*.05,.6+(i%5)*.06,.95);sizes.push(i%53===0?2.8:.8);}stars=pointCloud(positions,colors,sizes,expanding?3:2);filaments=new T.Group();nodes.forEach((a,i)=>{const nearest=nodes.map((b,j)=>({b,j,d:a.distanceTo(b)})).filter(x=>x.j!==i).sort((x,y)=>x.d-y.d).slice(0,3);nearest.forEach(({b,j})=>{if(j<i)return;const pts=[];for(let k=0;k<=24;k++){const t=k/24,p=a.clone().lerp(b,t);p.y+=Math.sin(t*Math.PI)*Math.sin(i)*.6;pts.push(p)}const l=new T.Line(new T.BufferGeometry().setFromPoints(pts),new T.LineBasicMaterial({color:0x658fe0,transparent:true,opacity:.28,depthWrite:false}));filaments.add(l);});});objects.add(filaments);}
 function nebula(){volumeUniforms={time:{value:0},density:{value:1},spectrum:{value:0}};volume=new T.Mesh(new T.SphereGeometry(14,48,32),new T.ShaderMaterial({side:T.BackSide,transparent:true,depthWrite:false,uniforms:volumeUniforms,vertexShader:'varying vec3 wp;void main(){wp=(modelMatrix*vec4(position,1.)).xyz;gl_Position=projectionMatrix*viewMatrix*vec4(wp,1.);}',fragmentShader:`varying vec3 wp;uniform float time,density,spectrum;float hash(vec3 p){return fract(sin(dot(p,vec3(127.1,311.7,74.7)))*43758.5453);}float n(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1)),f.x),f.y),f.z);}float fbm(vec3 p){return n(p)*.57+n(p*2.03)*.28+n(p*4.07)*.15;}void main(){vec3 ro=cameraPosition,rd=normalize(wp-ro);float b=dot(ro,rd),c=dot(ro,ro)-196.,d=b*b-c;if(d<0.)discard;float start=max(0.,-b-sqrt(d)),end=-b+sqrt(d),stepSize=(end-start)/56.;vec4 acc=vec4(0.);for(int i=0;i<56;i++){vec3 p=ro+rd*(start+(float(i)+.5)*stepSize);float r=length(p)/14.;vec3 q=p*.23+vec3(time*.015,0.,0.);float f=fbm(q+fbm(q*1.5)*2.);float shell=exp(-pow((length(p.xz)-6.)*.18,2.));float den=max(0.,f-.35)*1.4*(1.-smoothstep(.65,1.,r))*density;den*=.4+shell;vec3 col=mix(vec3(.08,.22,.7),vec3(1.,.39,.12),smoothstep(.4,.7,f));if(spectrum>.5&&spectrum<1.5)col=mix(vec3(.4,.04,.03),vec3(1.,.7,.22),f);if(spectrum>1.5)col=mix(vec3(.14,.04,.55),vec3(.1,.8,1.),f);float a=1.-exp(-den*stepSize*.6);acc.rgb+=(1.-acc.a)*col*a*(1.+f*1.7);acc.a+=(1.-acc.a)*a;if(acc.a>.97)break;}gl_FragColor=acc;}`}));objects.add(volume);const p=[],c=[],sz=[];for(let i=0;i<2600;i++){const a=i*2.39996,r=((i*.618)%1)*12;p.push(Math.cos(a)*r,Math.sin(i*3.3)*r*.4,Math.sin(a)*r);c.push(.7,.85,1);sz.push(i%20?1:4)}stars=pointCloud(p,c,sz,2);}
 function supernova(){const p=[],c=[],sz=[];for(let i=0;i<65000;i++){const y=1-2*(i+.5)/65000,r=Math.sqrt(1-y*y),a=i*2.39996,rr=3.5+(i%19)/19*2;p.push(Math.cos(a)*r*rr,y*rr,Math.sin(a)*r*rr);c.push(i%3?.2:1,.32+(i%7)*.08,i%3?1:.2);sz.push(.6+(i%13)/12)}stars=pointCloud(p,c,sz,4);core=new T.Sprite(new T.SpriteMaterial({map:sprite,color:0xa2ceff,blending:T.AdditiveBlending,transparent:true,depthWrite:false}));core.scale.setScalar(3);objects.add(core);filaments=new T.Mesh(new T.SphereGeometry(1,64,40),new T.MeshBasicMaterial({color:0xb7d2ff,wireframe:true,transparent:true,opacity:.08,depthWrite:false}));objects.add(filaments);}
 function build(){if(!scene)return;disposeObject(objects);pointUniforms=[];nodes=[];stars=dust=filaments=volume=core=null;eventAge=0;eventRunning=false;selected=null;$('#universe-age').value=0;if(mode==='galaxy'||mode==='collision')galaxy(mode==='collision');if(mode==='nebula')nebula();if(mode==='web'||mode==='expansion')web(mode==='expansion');if(mode==='supernova')supernova();renderer.orbitAutoScale=mode==='nebula'?.8:Infinity;if(renderer.orbitResize)renderer.orbitResize();else if(mode==='nebula'&&graphicsQuality()==='auto')renderer.setPixelRatio(Math.min(.8,renderer.getPixelRatio()));nav.reset(mode==='web'||mode==='expansion'?48:mode==='nebula'?34:mode==='collision'?44:32);updateText();}
 section.querySelectorAll('[data-universe]').forEach(b=>b.onclick=()=>{mode=b.dataset.universe;section.querySelectorAll('[data-universe]').forEach(x=>x.setAttribute('aria-pressed',x===b));updateText();build();});$('#universe-arms').onchange=build;$('#universe-age').oninput=e=>{eventAge=+e.target.value;eventRunning=false};$('#universe-burst').onclick=()=>{eventAge=0;eventRunning=true};$('#universe-pause').onclick=e=>{paused=!paused;e.currentTarget.setAttribute('aria-pressed',paused);e.currentTarget.textContent=paused?'Resume':'Pause'};$('#universe-auto').onclick=e=>{auto=!auto;e.currentTarget.setAttribute('aria-pressed',auto)};$('#universe-camera').onclick=()=>nav?.reset();root.addEventListener('pointerdown',()=>{auto=false;$('#universe-auto').setAttribute('aria-pressed',false)});$('#universe-capture').onclick=()=>{if(renderer)capture4K(renderer,scene,camera,'ORBIT-Universe-'+mode+'-4K.png',()=>pipeline.render(time))};
 let down=null;root.addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY});root.addEventListener('pointerup',e=>{if(!camera||!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>5)return;const r=root.getBoundingClientRect(),mouse=new T.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);if(nodes.length){let closest=Infinity;nodes.forEach((p,i)=>{const q=p.clone().multiplyScalar(mode==='expansion'?+$('#universe-scale').value:1).project(camera),d=Math.hypot(q.x-mouse.x,q.y-mouse.y);if(d<closest){closest=d;selected=i}});showSelection();}else if(stars){const ray=new T.Raycaster();ray.params.Points.threshold=.6;ray.setFromCamera(mouse,camera);const hit=ray.intersectObject(stars)[0];if(hit){const v=galaxyPoint(hit.index,120000,+$('#universe-arms').value);$('#universe-inspect').textContent=`SYNTHETIC STAR ${String(hit.index).padStart(6,'0')} / ${Math.round(v.temperature).toLocaleString()} K · generated population / not a cataloged star`;}}});
 function showSelection(){if(selected===null||!nodes[selected])return;const d=nodes[selected].length()*30*(mode==='expansion'?+$('#universe-scale').value:1);$('#universe-inspect').textContent=`CLUSTER ${selected+1} / ${d.toFixed(1)} Mpc · ${mode==='expansion'?hubbleVelocity(d,+$('#universe-hubble').value).toFixed(0)+' km/s / v = H₀d':'generated cosmic-web node'}`;}
 function frame(now){requestAnimationFrame(frame);const dt=Math.min(.05,(now-last)/1000)||0;last=now;if(!visible||document.hidden||!renderer)return;const moving=api.getState().motion&&!paused;if(moving){time+=dt*+$('#universe-speed').value;if(eventRunning){eventAge=Math.min(1,eventAge+dt*.055*+$('#universe-speed').value);$('#universe-age').value=eventAge;if(eventAge===1)eventRunning=false}}if(auto&&moving)nav.setPose({yaw:time*.035,pitch:mode==='nebula'?.2:.55});nav.update(dt,api.getState().motion);const spectrum=['natural','infrared','energy'].indexOf($('#universe-spectrum').value);for(const u of pointUniforms){u.time.value=time;u.spectrum.value=spectrum;u.age.value=eventAge;u.scaleFactor.value=+$('#universe-scale').value;u.pixelRatio.value=renderer.getPixelRatio();}if(stars){stars.visible=$('#universe-stars').checked;stars.geometry.setDrawRange(0,Math.floor(stars.geometry.attributes.position.count*+$('#universe-density').value/100));}if(dust){dust.visible=$('#universe-dust').checked;dust.material.uniforms.gain.value=.3*+$('#universe-gas').value;}if(volume){volume.visible=$('#universe-dust').checked;volumeUniforms.time.value=time;volumeUniforms.density.value=+$('#universe-gas').value;volumeUniforms.spectrum.value=spectrum}if(filaments){filaments.visible=$('#universe-filaments').checked;filaments.scale.setScalar(mode==='expansion'?+$('#universe-scale').value:mode==='supernova'?.4+eventAge*12:1)}if(core)core.visible=$('#universe-stars').checked;if(core&&mode==='supernova')core.scale.setScalar(.7+Math.exp(-eventAge*9)*7);pipeline.enabled=$('#universe-bloom').checked;pipeline.render(time);uiClock+=dt;if(uiClock>.5){uiClock=0;$('#universe-stats').textContent=`${renderer.domElement.width.toLocaleString()} × ${renderer.domElement.height.toLocaleString()} / ${graphicsQuality().toUpperCase()} · ${stars?Math.floor(stars.geometry.drawRange.count).toLocaleString():'VOLUMETRIC'} LUMINOUS SAMPLES`;if(mode==='expansion')showSelection();}}
 updateText();new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible&&!started)initialize();},{rootMargin:'200px'}).observe(section);
 if(location.hash==='#universe')section.scrollIntoView();
}
